package com.nextrade.domain.ledger; import com.nextrade.common.enumtype.LedgerEntryType; import com.nextrade.common.identifier.*; import com.nextrade.common.valueobject.*; public record TradeCredit(LedgerEntry entry) { public TradeCredit { if(entry.type()!=LedgerEntryType.TRADE_CREDIT) throw new IllegalArgumentException("Wrong ledger type"); } public static TradeCredit of(UserId user,Money amount,String reference){ return new TradeCredit(new LedgerEntry(LedgerEntryId.generate(),user,LedgerEntryType.TRADE_CREDIT,amount,reference,java.time.Instant.now())); } }